SELECT i.i_category, i.i_brand, SUM(wr.wr_return_amt) AS total_return_amount, AVG(inv.inv_quantity_on_hand) AS avg_quantity_on_hand FROM web_returns wr JOIN item i ON wr.wr_item_sk = i.i_item_sk JOIN inventory inv ON inv.inv_item_sk = i.i_item_sk WHERE i.i_category = 'Home                                              ' AND inv.inv_date_sk = 2450857 GROUP BY i.i_category, i.i_brand
